        import random
        import time

        LANGUAGE_WRAPPER = 'Consider the sequence {a_n} of positive real terms defined by a_1 = {a_1}. For integers {m} \\ge 3, {c} > 0, and {d}, the sequence satisfies the nonlinear recurrence for all n \\ge 1:\\n\\nT_{\\,{m}}({c}\\,a_{n+1} + {d}) = {c}\\,a_n + {d},\\n\\nwhere T_k denotes the k-th Chebyshev polynomial of the first kind, equivalently T_k(\\cosh x) = \\cosh(kx). Find a closed-form expression for a_n in terms of n only.\\n\\nAfter solving the above problem, please output your final answer in the following format:\\n### The final answer is: \\boxed{<your answer>}\\nExample:\\n### The final answer is: \\boxed{2n+1}\\nYour final answer must be a formula containing n. Do not include any restrictions on the value of n in your final answer. The final answer should be given as precisely as possible (using LaTeX symbols such as \\sqrt, \\frac, \\pi, etc.). If the final answer involves a decimal approximation, it must be accurate to at least four decimal places.'

        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        def generator(rng):
    # Generate parameters for the Chebyshev-based recurrence:
    # T_m(c a_{n+1} + d) = c a_n + d, with m >= 3, c > 0, and positivity ensured.
    # We ensure c*a_1 + d > 1 for the arcosh domain and (1 - d)/c > 0 for positivity of the limit.
    for _ in range(1000):
        m = rng.randint(3, 6)  # degree 3..5 (occasionally 6)
        c = rng.randint(1, 4)  # modest positive integer scale
        d = rng.randint(-5, 0)  # ensure (1 - d)/c > 0 and avoid pathological triviality
        a1 = rng.randint(2, 20)  # positive initial term
        y1 = c * a1 + d
        if y1 > 1:  # domain for arcosh
            # Optional extra difficulty: avoid y1 very small integer near 2 to reduce chances of simplification.
            # Also avoid c=1,d=0,m=3,a1=2 exact small cases too simple.
            if not (m == 3 and c == 1 and d == 0 and a1 in (2,3)):
                return {"m": m, "c": c, "d": d, "a_1": a1}
    # Fallback in the unlikely event no valid sample is found
    m, c, d, a1 = 3, 2, 0, 7
    return {"m": m, "c": c, "d": d, "a_1": a1}

        import math

def verifier(assign):
    # Validate inputs and return (True, answer) with the closed-form.
    # The closed-form derives from setting y_n = c a_n + d and using T_m(y_{n+1}) = y_n with T_m(cosh t) = cosh(m t).
    # Then y_n = cosh(arcosh(y_1) / m^{n-1}), so a_n = (y_n - d)/c.
    try:
        m = int(assign.get('m'))
        c = int(assign.get('c'))
        d = int(assign.get('d'))
        a1 = assign.get('a_1')
        if a1 is None:
            # Missing required slot
            return (False, None)  # missing a_1
        a1 = float(a1)
    except Exception:
        return (False, None)  # type conversion error

    # Domain and difficulty checks
    if m < 3:
        return (False, None)  # enforce harder-than-seed: m >= 3
    if c <= 0:
        return (False, None)  # c must be positive
    y1 = c * a1 + d
    if y1 <= 1:
        return (False, None)  # arcosh domain and uniqueness of hyperbolic branch
    # Positivity of the entire sequence (limit as n -> infinity is (1 - d)/c)
    if (1 - d) <= 0:
        return (False, None)  # would eventually become non-positive

    # Construct the exact LaTeX answer. We keep integers intact in the expression.
    # a_n = (1/c) * ( cosh( arcosh(y1) / m^{n-1} ) - d )
    # Use integer formatting for y1 when possible
    if abs(y1 - int(y1)) < 1e-12:
        y1_str = str(int(round(y1)))
    else:
        # In practice y1 is integer under our generator, but handle generality
        y1_str = ("%0.10g" % y1)

    ans = "\\frac{1}{%d}\\left(\\cosh\\left(\\frac{\\operatorname{arcosh}(%s)}{%d^{n-1}}\\right) - %d\\right)" % (c, y1_str, m, d)
    return True, ans


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
